#!/usr/bin/env python3
import yaml

def get_version_from_yaml():
    with open('.ai-project.yml', 'r') as file:
        data = yaml.safe_load(file)
    return data['governance']['version']

if __name__ == '__main__':
    version = get_version_from_yaml()
    print(version.strip())

